    id: "blessing-eulogia-bread",
    title: "صلاة على خبز البركة (صلوات تبريك ١)",
    role: "الكاهن",
    text: `صلاةٌ على خبزِ البَركةِ أي خبزِ الأولوجيَّةِ

أيُّها السَّيِّدُ الرَّبُّ الإلهُ ضابطُ الكُلِّ، مُعطيَ الخيراتِ، الَّذي يُعطي طعامًا لكُلِّ جسدٍ.

أنتَ المُعطي طعامًا لعبيدِكَ الَّذينَ يخافُونَكَ، ابسُط يَمينَكَ غَيرَ المرئيَّةِ.

[يَرشُمُ الكاهنُ الخُبزَ ثلاثةَ رُشومٍ وهو على يدِهِ:]
[أولاً:] وبارِكْ على هذا الخُبزِ الموضوعِ على يدَيَّ.
[ثانيًا:] واجعلْ فيهِ بَرَكَتَكَ.
[ثالثًا:] ونعمَتَكَ.

لِكَيْ يَصيرَ شِفاءً لكُلِّ الآخِذينَ مِنهُ، خلاصًا للنَّفسِ وطهارَةً للجسدِ، وغُفرانًا للخطَايا.

قُوَّةُ الثَّالُوثِ المُقَدَّسِ تكونُ على هذا الخُبزِ وعلى مُعطيهِ وعلى آخِذِه وكُلِّ المُهتمِّينَ بهِ. اللهُمَّ برحمَتِكَ.

[يَرشُمُ قائلاً:]
بَارِكْ هذِه الأولوجيَّةَ، آمينْ.

بالنعمَةِ...`,
