    copticText: `Ⲏⲡⲡⲉ ϥⲭⲏ ⲛⲉⲙⲁⲛ ϩⲓⲭⲉⲛ ⲧⲁⲓⲧⲣⲁⲡⲉⲍⲁ ⲙ̀ⲫⲟⲟⲩ ⲛ̀ⲭⲉ Ⲉⲙⲙⲁⲛⲟⲩⲏⲗ Ⲡⲉⲛⲛⲟⲩⲧⲉ · ⲡⲓϣⲏⲃ ⲛ̀ⲧⲉ Ⲫϯ ⲫⲏⲉⲧⲱⲗ ⲙ̀ⲫⲛⲟⲃⲓ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ ⲧⲏⲣϥ.

Ⲫⲏⲉⲧⲥⲉⲙⲥⲓ ϩⲓⲭⲉⲛ ⲡⲓⲑⲣⲟⲛⲟⲥ ⲛ̀ⲧⲉ ⲡⲉϥⲱⲟⲩ. Ⲫⲏⲉⲧⲟⲣⲟϫⲓ ⲉⲣⲁⲧⲟⲩ ⲛⲁϩⲣⲁϥ ⲛ̀ⲭⲉ ⲛⲓⲧⲁⲅⲙⲁ ⲧⲏⲣⲟⲩ ⲛ̀ⲉⲡⲟⲩⲣⲁⲛⲓⲟⲛ. Ⲫⲏⲉⲧⲟⲩⲥⲱⲥ ⲉⲣⲟϥ ⲛ̀ⲭⲉ ⲛⲓⲁⲅⲅⲉⲗⲟⲥ ϩⲉⲛ ⲛⲓⲥⲙⲏ ⲛ̀ⲧⲉ ⲡⲓⲥⲙⲟⲩ · ⲟⲩⲟϩ ⲉⲧⲣⲓⲧⲟⲩ ⲉⲣⲟⲣⲱϣⲧ ⲙ̀ⲙⲟϥ ⲛ̀ⲭⲉ ⲛⲓⲁⲣⲭⲏⲁⲅⲅⲉⲗⲟⲥ. Ⲡⲓϥⲧⲟⲩ ⲛ̀ⲍⲱⲟⲛ ⲛⲁⲥⲱⲙⲁⲧⲟⲥ ⲥⲉⲭⲱ ⲙ̀ⲡⲓⲥⲩⲙⲛⲟⲥ ⲛ̀ⲧⲉ ⲡⲓⲧⲣⲓⲥⲁⲅⲓⲟⲥ.

Ⲟⲩⲟϩ ⲡⲓⲭⲟⲣⲟⲥ ⲉⲧⲟⲣ ⲙ̀ⲡⲣⲉⲥⲃⲩⲧⲉⲣⲟⲥ ⲥⲉϩⲉⲙⲥⲓ ϩⲓⲭⲉⲛ ⲛⲟⲩⲑⲣⲟⲛⲟⲥ · ⲉⲣⲉ ⲭⲟⲣⲧ ⲉⲧⲟⲣ ⲛ̀ⲭⲗⲟⲙ ⲛ̀ⲛⲟⲩⲃ ϩⲓⲭⲉⲛ ⲛⲟⲩⲁⲫⲏⲟⲩⲓ · ⲉⲣⲉ ⲭⲟⲣⲧ ⲉⲧⲟⲣ ⲙ̀ⲫⲣⲁⲗⲏ ⲛ̀ⲛⲟⲩⲃ ϩⲉⲛ ⲛⲟⲩϫⲓϫ ⲉⲣⲙⲉⲥ ⲛ̀ⲥⲑⲟⲓⲛⲟⲩϥⲓ · ⲉⲧⲉ ⲛⲓⲡⲣⲟⲥⲉⲩⲭⲏ ⲛ̀ⲧⲉ ⲛⲓⲁϫⲓⲟⲥ · ⲟⲩⲟϩ ⲥⲉⲟⲣⲱϣⲧ ⲙ̀ⲡⲉⲩⲑⲟ ⲙ̀ⲫⲏⲉⲧⲟⲛϩ ϣⲁ ⲉⲛⲉϩ ⲛ̀ⲧⲉ ⲡⲓⲉⲛⲉϩ.

Ⲟⲩⲟϩ ⲡⲓϣⲉ ⲉⲙⲉ ⲉⲧⲟⲣ ⲛ̀ⲙⲱⲟⲩ ⲛⲓⲡⲁⲣⲑⲉⲛⲟⲥ ⲛⲁⲧⲱⲗⲉⲃ ⲥⲉⲥⲱⲥ ⲉⲠⲟ̄ⲥ̄ ⲉⲣⲭⲱ ⲙ̀ⲙⲟⲥ · ⲭⲉ ⲁϫⲓⲟⲥ ⲁϫⲓⲟⲥ ⲁϫⲓⲟⲥ · ⲁⲙⲏⲛ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ.

Ⲁⲛⲟⲛ ⲇⲉ ϩⲱⲛ ⲧⲉⲛⲟⲣⲱϣⲧ ⲛ̀ⲧⲧⲣⲓⲁⲥ ⲉⲑⲣ ⲧⲉⲛⲥⲱⲥ ⲉⲣⲟⲥ ⲉⲛⲭⲱ ⲙ̀ⲙⲟⲥ. Ⲭⲉ ϥⲟⲩⲁⲃ ⲛ̀ⲭⲉ Ⲫϯ Ⲫⲓⲱⲧ ⲡⲓⲡⲁⲛⲧⲟⲕⲣⲁⲧⲱⲣ · ⲁⲙⲏⲛ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ. Ⲭⲟⲩⲁⲃ ⲛ̀ⲭⲉ ⲡⲉϥⲙⲟⲛⲟⲅⲉⲛⲏⲥ ⲛ̀ϣⲏⲣⲓ Ⲓⲏⲥⲟⲩⲥ Ⲡⲭ̄ⲥ̄ Ⲡⲉⲛⲟ̄ⲥ̄ · ⲁⲙⲏⲛ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ. Ⲭⲟⲩⲁⲃ ⲛ̀ⲭⲉ Ⲡⲓⲡⲛⲉⲩⲙⲁ ⲉⲑⲣ ⲙ̀ⲡⲁⲣⲁⲕⲗⲏⲧⲟⲛ · ⲁⲙⲏⲛ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ.

Ⲥⲟⲩⲁⲃ ⲟⲩⲟϩ ⲉⲙⲉⲥ ⲛ̀ⲱⲟⲩ ⲛ̀ⲭⲉ ⲧⲑⲉⲟⲧⲟⲕⲟⲥ ⲉⲑⲟⲩⲁⲃ ⲧⲁⲅⲓⲁ Ⲙⲁⲣⲓⲁ ⲧⲡⲁⲣⲑⲉⲛⲟⲥ · ⲁⲙⲏⲛ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ. Ⲥⲟⲩⲁⲃ ⲟⲩⲟϩ ⲉⲙⲉⲥ ⲛ̀ⲱⲟⲩ ⲛ̀ⲭⲉ ⲧⲁⲓⲉⲩⲥⲓⲁ · ⲑⲏⲉⲧⲁⲣϣⲁⲧ ϧⲁ ⲡⲱⲛϩ ⲙ̀ⲡⲓⲕⲟⲥⲙⲟⲥ ⲧⲏⲣϥ · ⲁⲙⲏⲛ ⲁⲗⲗⲏⲗⲟⲩⲓⲁ.

Ⲉⲑⲃⲉ ⲫⲁⲓ ⲁ ⲡⲉⲛⲥⲱⲧⲏⲣ ⲛⲁⲅⲁⲑⲟⲥ ϣⲱⲓ ⲉⲃⲟⲗ ⲉϥⲭⲱ ⲙ̀ⲙⲟⲥ · ⲭⲉ ⲡⲁⲥⲱⲙⲁ ⲟⲩϩⲣⲉ ⲙ̀ⲙⲏⲓ ⲧⲉ · ⲟⲩⲟϩ ⲡⲁⲥⲛⲟϥ ⲟⲩⲥⲱ ⲙ̀ⲙⲏⲓ ⲡⲉ. Ⲫⲏⲉⲑⲱⲣⲱⲙ ⲙ̀ⲡⲁⲥⲱⲙⲁ ⲟⲩⲟϩ ⲉⲧⲥⲱ ⲙ̀ⲡⲁⲥⲛⲟϥ ⲉϥⲉϣⲱⲡⲓ ⲛ̀ϩⲏⲧ · ⲟⲩⲟϩ ⲁⲛⲟⲕ ϩⲱ ⲉⲓⲉϣⲱⲡⲓ ⲛ̀ϩⲏⲧϥ.

Ⲅⲉⲛⲧⲥⲟ ⲉⲣⲟⲕ ⲡⲉⲛⲛⲏⲃ ⲙⲁⲧⲟⲩⲃⲟ ⲛ̀ⲛⲉⲛⲯⲩⲭⲏ ⲛⲉⲙ ⲛⲉⲛⲥⲱⲙⲁ ⲛⲉⲙ ⲛⲉⲛⲡⲛⲉⲩⲙⲁ. Ⲭⲉ ϩⲓⲛⲁ ϩⲉⲛ ⲟⲩϩⲏⲧ ⲉϥⲟⲩⲁⲃ · ⲛⲉⲙ ϩⲁⲛⲥⲫⲟⲧⲟⲩ ⲉⲧⲧⲟⲩⲃⲏⲟⲩⲧ · ⲛⲉⲙ ⲟⲩⲯⲩⲭⲏ ⲉⲁⲥⲃⲓⲟⲩⲱⲓⲛⲓ · ⲛⲉⲙ ⲟⲩϩⲟ ⲛⲁⲧⲃⲓϣⲱⲡⲓ · ⲛⲉⲙ ⲟⲩⲛⲁϩⲧ ⲛⲁⲧⲙⲉⲧϣⲟⲃⲓ · ⲛⲉⲙ ⲟⲩⲥⲩⲛⲓⲇⲏⲥⲓⲥ ⲉⲥⲧⲟⲩⲃⲏⲟⲩⲧ · ⲛⲉⲙ ⲟⲩϩⲩⲡⲟⲙⲟⲛⲏ ⲉⲥϩⲏⲕ ⲉⲃⲟⲗ · ⲛⲉⲙ ⲟⲩϩⲉⲗⲡⲓⲥ ⲉⲥⲧⲁⲭⲣⲏⲟⲩⲧ.

Ⲛ̀ⲧⲉⲛⲉⲣⲧⲟⲗⲙⲁⲛ ϩⲉⲛ ⲟⲩⲡⲁⲣⲣⲏⲥⲓⲁ ⲛⲁⲧⲉⲣϩⲟⲧ · ⲉⲧⲱⲃⲍ ⲙ̀ⲙⲟⲕ Ⲫϯ Ⲫⲓⲱⲧ ⲉⲑⲟⲩⲁⲃ ⲉⲧ ϩⲉⲛ ⲛⲓⲫⲏⲣⲓ ⲟⲩⲟϩ ⲉⲭⲟⲥ. Ⲭⲉ Ⲡⲉⲛⲓⲱⲧ...`,
